    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        scanf("%d%d", &a, &b);
        graph[a-1].push_back(b-1);
        indegree[b-1]++;
    }
    for (int i = 0; i < n; i++) {
        if (indegree[i] == 0)
            q.push(i);
    }
    while (!q.empty()) {
        int node = q.front();
        q.pop();
        for (int i = 0; i < graph[node].size(); i++) {
            if (visited[graph[node][i]] == false) {
                visited[graph[node][i]] = true;
                indegree[graph[node][i]]--;
                if (indegree[graph[node][i]] == 0)
                    q.push(graph[node][i]);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", i + 1);
    }
    printf("\n");
