    for ( size_t i = 0, j = s.size() - 1; i < j; ++i, --j ) {
        if ( s[i]!= s[j] ) {
            return false;
        }
    }
    return true;
}

string reverse( const string& s) {
    string r;
    for ( size_t i = 0; i < s.size(); ++i ) {
        r.push_back( s[ s.size() - 1 - i ] );
    }
    return r;
}

int main() {
    string s;
    cout << "Quelle chaine voulez-vous inverser? : ";
    getline( cin, s );
    if ( is_palindrome( s ) ) {
        cout << "\"" << s << "\"" << " est un palindrome." << endl;
    } else {
        string rs = reverse( s );
        cout << "\"" << s << "\"" << " n'est pas un palindrome." << endl;
        cout << "Reversed string is \"" << rs << "\"." << endl;
    }
}
