import java.util.Objects;

public class MethodVisitorImpl implements MethodVisitor {

    private final StringBuilder code;

    public MethodVisitorImpl() {
        this.code = new StringBuilder();
    }

    @Override
    public void visit(Method method) {
        Objects.requireNonNull(method, "Method cannot be null");

        final String simpleName = method.getName().split("\\.")[method.getName().split("\\.").length - 1];
        final String simpleNameWithNoSpaces = WordUtils.capitalize(simpleName.replace(".", "_"));

        if (code.length() > 0) {
            code.append("\n");
        }
        code.append("public void ").append(simpleNameWithNoSpaces).append("(");
        if (method.getParameters()!= null && method.getParameters().length > 0) {
            for (var parameter : method.getParameters()) {
                code.append(parameter.getType().getSimpleName());
                code.append(" ").append(parameter.getName());
                if (parameter!= method.getParameters()[method.getParameters().length - 1]) {
                    code.append(", ");
                }
            }
        }
        code.append("){\n");
        if (method instanceof MethodImpl) {
            ((MethodImpl) method).generateCode(code, 4);
        }
        code.append("}\n\n");
    }

    @Override
    public StringBuilder get() {
        return code;
    }
}
