package org.codenarc.rule.basic;

import static org.codenarc.rule.AbstractRule.EQUALITY_CHECK_RULE;

import java.util.List;

import org.antlr.v4.runtime.tree.ParseTree;
import org.codenarc.rule.AbstractRule;
import org.codenarc.rule.IRule;
import org.codenarc.rule.RuleVisitor;
import org.codenarc.rule.RuleContext;

public class EqualsHashCode extends AbstractRule {

    public EqualsHashCode() {
        super(EQUALITY_CHECK_RULE);
    }

    @Override
    public void visitCodeFragment(RuleContext context) {
        RuleContext codeContext = new RuleContext(context);
        RuleVisitor visitor = new RuleVisitor(codeContext.getJavaParser(), codeContext);
        codeContext.setCodeTree(visitor.walk(getAst()));
        List<Boolean> b = visitor.equalsHashCode();
        if (b.get(0) &&!b.get(1)) {
            codeContext.addMessage(EQUALITY_CHECK_RULE, 1);
        }
    }
}
