import com.github.reinierk.trivia.question.*;

import java.util.concurrent.ThreadLocalRandom;

public class Trivia {
    private List<Question> questions;

    private int totalQuestions;
    private int answeredQuestions;
    private boolean done;
    private int correctAnswers; 

    public Trivia(List<Question> questions) {
        this.questions = questions;
        this.totalQuestions = questions.size();
        this.done = false;
        this.correctAnswers = 0;
    }

    private Question randomQuestion() {
        List<Question> remainingQuestions = this.questions.stream().filter(q ->!q.isAnswered()).collect(Collectors.toList());
        int randomIndex = ThreadLocalRandom.current().nextInt(remainingQuestions.size());
        return remainingQuestions.get(randomIndex);
    }

    public boolean isDone() {
        return this.done;
    }

    public void nextQuestion() {
        if (this.done) return;

        Question currentQuestion = this.randomQuestion();
        Answer currentAnswer = currentQuestion.nextAnswer();

        if (currentAnswer!= null) {
            if (currentAnswer.isCorrect()) {
                this.correctAnswers++;
            }

            currentQuestion.setAnswered(true);
            this.answeredQuestions++;

            if (this.answeredQuestions == this.totalQuestions) {
                this.done = true;
            }
        }        
    }

    public boolean isFinalQuestion() {
        Question currentQuestion = this.randomQuestion();
        if (currentQuestion!= null) {
            return currentQuestion.isFinalQuestion();
        }

        return false;
    }

    public Answer getNextAnswer() {
        Question currentQuestion = this.randomQuestion();
        if (currentQuestion!= null) {
            return currentQuestion.nextAnswer();
        }

        return null;
    }

    public int getCorrectAnswers() {
        return this.correctAnswers;
    }
