private static boolean checkZip(File zip, String[] paths, String zipRoot) throws Exception {
    ZipInputStream zipInput = new ZipInputStream(new FileInputStream(zip));
    ZipEntry entry = zipInput.getNextEntry();

    while(entry!= null) {
        if (paths.length > 0) {
            for (String s : paths) {
                if (entry.getName().contains(s)) {
                    return false;
                }
            }
        }

        String name = entry.getName();
        if (!name.endsWith("/")) {
            System.out.println("Checking " + name);
            if (name.contains("..")) {
                System.out.println("Found.. in " + name);
                return false;
            }

            int lastSlash = zipRoot.length();
            for (int i = name.length() - 1; i >= 0; i--) {
                if (name.charAt(i) == '/') {
                    lastSlash = i;
                    break;
                }
            }

            String path = name.substring(0, lastSlash);
            if (!name.equals(lastSlash)) {
                path = path + "/";
            }

            if (path.contains("..")) {
                if (!path.equals(zipRoot) && path.substring(0, path.length() - 1).endsWith("/")) {
                    System.out.println("Found.. in " + name);
                    return false;
                }
            }
        }

        entry = zipInput.getNextEntry();
    }

    return true;
}
