import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * This method extracts a zip file to the destination directory specified by the path argument.
     * 
     * After validating the path, this method iterates over the members of the zip archive and tries to avoid
     * walking up the directory hierarchy by checking that the member name does not contain '..'.
     */
<|user|>
    public void extract(String path) throws Exception {
        File zip = new File(path);
        ZipInputStream zis = new ZipInputStream(new FileInputStream(zip));

        ZipEntry entry;
        while ((entry = zis.getNextEntry())!= null) {
            String name = entry.getName();
            if (name.indexOf('..') < 0) {
                File out = new File(zip.getParent(), name);
                if (entry.isDirectory()) {
                    out.mkdirs();
                } else {
                    copy(out, zis);
                }
            }
        }
    }

