Node* createNode(int data)
{
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(Node* head, int data)
{
    Node* newNode = createNode(data);
    Node* temp = head;
    while (temp->next!= NULL)
        temp = temp->next;
    temp->next = newNode;
}

int findNode(Node* head, int data)
{
    Node* temp = head;
    while (temp!= NULL)
    {
        if (temp->data == data)
            return 1;
        temp = temp->next;
    }
    return 0;
}

void printList(Node* head)
{
    Node* temp = head;
    while (temp!= NULL)
    {
        printf("%d\n", temp->data);
        temp = temp->next;
    }
}

