    FileInputStream stream = new FileInputStream(zipFile);
    ZipInputStream zipStream = new ZipInputStream(stream);
    ZipEntry ze;
    String zipEntryName;
    String memberName;
    String newPath;

    ze = zipStream.getNextEntry();
    while (ze!= null) {
        zipEntryName = ze.getName();
        if (zipEntryName.contains("..")) throw new Exception("O código zip não pode conter '..'");
        memberName = zipEntryName.substring(zipEntryName.lastIndexOf("/")+1);
        newPath = targetDirectory + "/" + memberName;
        if (new File(newPath).exists() &&!new File(newPath).isDirectory())
            throw new Exception("Arquivo de destino já existe.");
        else if (!new File(newPath).exists() &&!new File(newPath).mkdirs())
            throw new Exception("Não foi possível criar o diretório de destino.");
        extractMember(zipStream, newPath);
        ze = zipStream.getNextEntry();
    }
}

public void extractMember(ZipInputStream zipStream, String newDirectory) throws Exception {
    if (new Directory(newDirectory).exists()) {
        FileInputStream stream = new FileInputStream(newDirectory);
        ZipInputStream memberStream = new ZipInputStream(stream);
        ZipEntry ze = memberStream.getNextEntry();
        String memberName;
        while (ze!= null) {
            memberName = ze.getName();
            if (memberName.contains("..")) throw new Exception("O membro '" + ze.getName() + "' do arquivo zip não pode conter '..'");
            extractMember(memberStream, newDirectory + "/" + memberName);
            ze = memberStream.getNextEntry();
        }
    }
    else {
        FileOutputStream stream = new FileOutputStream(newDirectory);
        int b = 0;
        while ((b = zipStream.read()) > -1)
            stream.write(b);
        stream.close();
    }
