package fr.insalyon.dkit.jcode.utils;

import java.io.File;
import java.util.ArrayList;

/**
 * Classe de gestion d'une archive
 *
 * @author 
 */
public class JarFileManager extends FileManager {

    public JarFileManager(File fichier) {
        super(fichier);
    }

    @Override
    public boolean exists() {
        return this.fichier.exists();
    }

    @Override
    public ArrayList<String> getFiles() {

        ArrayList<String> fileNames = new ArrayList<>();

        try {
            org.apache.tools.zip.ZipFile zip = new org.apache.tools.zip.ZipFile(this.fichier);
            org.apache.tools.zip.ZipEntry entry;

            while ((entry = zip.getNextEntry())!= null) {
                fileNames.add(entry.getName());
            }

            zip.close();
        } catch (Exception e) {
            return null;
        }

        return fileNames;
    }
}
