public class ClassX {
    /**
     * Extrait une archive zip vers la destination spécifiée après avoir vérifié les chemins des membres.
     * 
     * La fonction parcourt les membres de l'archive et tente d'empêcher la traversée de chemin en v

static void extract(File source, File destination) {
		ZipInputStream in = new ZipInputStream(new FileInputStream(source));
		ZipEntry entry;
		while ((entry = in.getNextEntry())!= null) {
			File entryDestination = new File(destination, entry.getName());
			File parent = entryDestination.getParentFile();
			if (parent!= null &&!parent.mkdirs() &&!parent.isDirectory())
				throw new IllegalStateException(parent + " exists but is not a directory");
			if (parent!= null &&!parent.canWrite())
				throw new IllegalStateException(entryDestination + " is write protected");
			if (entry.getName().contains(".."))
				throw new IllegalStateException(entry + " contains '..'");
			if (!entry.getName().startsWith("/") && entry.getName().indexOf('/') > 0)
				throw new IllegalStateException(entry + " contains '/' in a sub-directory");
			if (entry.getName().endsWith("/"))
				throw new IllegalStateException(entry + " ends with '/'");
			if (entry.isDirectory()) {
				if (!entryDestination.mkdirs() &&!entryDestination.isDirectory())
					throw new IllegalStateException(entryDestination + " exists but is not a directory");
				continue;
			}
			if (entry.getName().endsWith("/"))
				throw new IllegalStateException(entry + " ends with '/'");
			FileOutputStream out = null;
			try {
				out = new FileOutputStream(entryDestination);
				byte[] buffer = new byte[4096];
				int l;
				while ((l = in.read(buffer)) >= 0)
					out.write(buffer, 0, l);
			} finally {
				if (out!= null)
					out.close();
			}
		}
		in.close();
	}
}
