import java.util.ArrayList;
import java.util.List;

import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import javax.persistence.criteria.CriteriaBuilder;
import javax.persistence.criteria.CriteriaQuery;
import javax.persistence.criteria.Root;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.thesis.core.api.domain.jpa.Assignment;
import org.thesis.core.api.domain.jpa.Question;
import org.thesis.core.api.repositories.jpa.AssignmentRepository;
import org.thesis.core.api.repositories.jpa.QuestionRepository;
import org.thesis.core.api.services.QuestionService;

@Service
@Transactional
public class QuestionServiceImpl implements QuestionService {

    /**
     * Logger for this class
     */
    private static final Log logger = LogFactory.getLog(QuestionServiceImpl.class);

    @Autowired
    private QuestionRepository questionRepository;

    @Autowired
    private AssignmentRepository assignmentRepository;

    @PersistenceContext
    private EntityManager entityManager;

	@Override
	public List<Question> getQuestionList(String id) {
		CriteriaBuilder cb = entityManager.getCriteriaBuilder();
    	CriteriaQuery<Question> query = cb.createQuery(Question.class);
    	Root<Question> root = query.from(Question.class);

    	query.select(root)
    		.where(cb.equal(root.get("assignment"), assignmentRepository.findOne(id)));

    	List<Question> questionList = new ArrayList<Question>();
    	questionList.addAll(questionRepository.findAll(query));

        return questionList;
	}

}
