package com.github.cormin.leetcode.easy;

import java.util.HashMap;
import java.util.Map;

public class NoC1201_NoC1202 {

    public int maxSatisfaction(int[] satisfaction) {
        int n = satisfaction.length;
        int[] s = new int[n + 1];
        Map<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int x = satisfaction[i];
            map.put(i, x);
        }

        // n-1 to 0, n to 0, 0 to 0
        for (int x = n; x > 0; x--) {
            int max = 0, sum = 0;
            for (int i = 0; i < x; i++) {
                sum += map.get(i);
                if (sum > max) {
                    max = sum;
                }
            }
            s[x] = max;
        }

        int ans = 0;
        for (int i = 1; i <= n; i++) {
            ans = Math.max(ans, s[i]);
        }
        return ans;
    }

    // Solution 2

    public int maxSatisfaction2(int[] satisfaction) {
        int max = 0;
        int[] s = new int[satisfaction.length];

        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < satisfaction.length; i++) {
            if (satisfaction[i] > 0) {
                map.put(i, satisfaction[i]);
            }
        }

        for (int i = satisfaction.length - 1; i >= 0; i--) {
            if (satisfaction[i] < 0) {
                int sum = 0;
                for (int j = i; j < satisfaction.length; j++) {
                    sum += map.get(j);
                    if (sum > max) {
                        max = sum;
                    }
                }
            }
        }
        return max;
    }

}

