package io.github.bopbi.bopbi.core.util;

import java.util.ArrayList;
import java.util.List;

public class StringManipulator {

    public static String removeLineBreak(String input) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            if (input.charAt(i)!= '\n' && input.charAt(i)!= '\r')
                builder.append(input.charAt(i));
        }
        return builder.toString();
    }

    public static String[] getLines(String input) {
        String[] lines = input.split("\n");
        List<String> linesTrimmed = new ArrayList<>();
        for (String line : lines) {
            String trimmedLine = line.trim();
            if (trimmedLine.length() > 0)
                linesTrimmed.add(trimmedLine);
        }
        return linesTrimmed.toArray(new String[0]);
    }

    public static String getLine(int index, String[] lines) {
        if (index >= lines.length)
            throw new IndexOutOfBoundsException("index larger than array length");
        return lines[index].trim();
    }

    public static String[] getLines(int start, int end, String[] lines) {
        String[] result = new String[end - start];
        int j = 0;
        for (int i = start; i < end; i++)
            result[j++] = lines[i].trim();
        return result;
    }
}
