 * Passive data-object representing the resources in the resource manager.
 * You must not alter any of the given public fields other than {@link Resources#resources}.
 */
public class Resources implements Serializable {
	/**
	 * number of instances of all resources on stock.
	 */
	public Map<ResourceType, Integer> resources;

	/**
	 * Constructor that builds the Resources object.
	 * @param resourcesMap map representing the resources in the resource manager. (the map is a copy of the map given by the constructor)
	 */
	public Resources(Map<ResourceType, Integer> resourcesMap){
		resources = resourcesMap;
	}

	/**
	 * Gets the amount of resources of the specific resource type that are left.
	 * @param resource the resource of the type that the resources are requested from.
	 * @return the amount of resources that are left.
	 */
	public int get(ResourceType resource){
		return resources.get(resource);
	}

	/**
	 * Decrease the amount of resources of a specific resource type by one.
	 * @param resource the resource of the type that the resources are requested from.
	 * @return True if the operation is succeed.
	 */
	public boolean consume(ResourceType resource){
		if (resources.get(resource) - 1 == 0){
			resources.remove(resource);
			return true;
		}
		if (resources.get(resource) - 1 > 0){
			resources.replace(resource, resources.get(resource) - 1);
			return true;
		}
		return false;
	}

	/**
	 * Add the amount of resources of a specific resource type by one.
	 * @param resource the resource of the type that the resources are requested from.
	 * @return True if the operation is succeed.
	 */
	public boolean add(ResourceType resource){
		if (!resources.containsKey(resource)){
			resources.put(resource, 1);
			return true;
		}
		resources.replace(resource, resources.get(resource) + 1);
		return true;
	}
}
