import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    private static final Pattern COMMAND = Pattern.compile("(\\S+)(?:\\s+(.+))?");

    public static void main(String... args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            while ((line = reader.readLine())!= null) {
                Matcher m = COMMAND.matcher(line);
                if (!m.matches()) {
                    System.err.println("Format Error");
                    continue;
                }
                String command = m.group(1);
                if ("mailcap".equals(command)) {
                    String subcommand = m.group(2);
                    if (subcommand.contains("||")) {
                        System.err.println("Format Error");
                        continue;
                    }
                    if ("findmatch".equals(subcommand)) {
                        String mime_type = m.group(3);
                        String filename = m.group(4);
                        System.out.println(getViewer(mime_type, filename));
                        continue;
                    }
                }
                if ("exit".equals(command)) {
                    System.exit(0);
                }
                System.err.println("Command not found: " + command);
            }
        }
    }

    private static String getViewer(String mime_type, String filename) {
        if (Arrays.asList("text/plain").contains(mime_type)) {
            return String.join("\n", getPlainViewer(filename));
        }
        if (Arrays.asList("text/html").contains(mime_type)) {
            return String.join("\n", getHtmlViewer(filename));
        }
        if (Arrays.asList("text/xml").contains(mime_type)) {
            return String.join("\n", getXmlViewer(filename));
        }
        System.err.println("Not supported: " + mime_type);
        return "";
    }

    private static String[] getPlainViewer(String filename) {
        return new String[] { "more", filename };
    }

    private static String[] getHtmlViewer(String filename) {
        return new String[] { "x-www-browser", filename };
    }

