        while (true) {
            int c;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
                c = reader.read();
                if (Character.isWhitespace(c)) continue;
            } catch (IOException e) {
                c = -1;
            }
            if (c == 'x') break;
            if (c == '[') test.move(1);
            if (c == ']') test.move(-1);
        }
        System.out.println(test.check());
        System.exit(0);
    }

    private static class Test {
        private int pos;

        Test() {
            pos = 0;
        }

        void move(int move) {
            if (move == 1) pos++;
            if (move == -1) pos--;
            if (pos < 0) pos = 0;
        }

        int check() {
            if (pos == 0) return 0;
            for (int i = 0; i < pos; i++) {
                if (i % 4 == 0) return i + 1;
            }
            return pos + 1;
        }
    }
}
