// 1, 2, 3, 4, 5, 6, 7, 8 
vector<int> palikka_pyoristys(vector<int> tarkistusarvot, int pyoristysnumero)
{
    vector<int> ret;
    vector<int> sumat;
    for (int i = 0; i < tarkistusarvot.size(); i++)
        sumat.push_back(tarkistusarvot.at(i) + pyoristysnumero);
    sort(sumat.begin(), sumat.end());
    sumat.erase(unique(sumat.begin(), sumat.end()), sumat.end());
    for (int i = 0; i < sumat.size(); i++)
    {
        int laske = 0;
        for (int j = 0; j < tarkistusarvot.size(); j++)
        {
            if (sumat.at(i) == tarkistusarvot.at(j) + pyoristysnumero)
                laske++;
        }
        if (laske >= 2)
        {
            ret.push_back(sumat.at(i) - pyoristysnumero);
            ret.push_back(sumat.at(i));
            return ret;
        }
    }

    return ret;
}

