    private void puhdistaSyöte(String syöte) {
        määritetty = "";
        for (int i = 0; i < syöte.length(); i++) {
            char c = syöte.charAt(i);
            if (c!= '&' && c!= '.' && c!='') {
                määritetty += c;
            } else if (c == '&') {
                määritetty += '&';
            }
        }
    }

    /**
     * Palauttaa määritetyn vastauksen.
     * 
     * @return määritetty Vastaus.
