public static String cleanInput(String input) {
    StringBuilder builder = new StringBuilder();
    char prev ='';
    for(char c: input.toCharArray()) {
        if(c =='') {
            continue;
        }
        if(c == '&') {
            while(prev!= '\t' && prev!= '\n' && prev!= '&') {
                prev = builder.deleteCharAt(builder.length() - 1).charAt(builder.length() - 1);
            }
        }
        prev = c;
        builder.append(c);
    }
    return builder.toString();
}

