package net.acayote.training.exercises.ex07_07;

import java.util.Scanner;

/**
 * Write a program that reads ten numbers and saves them in an array.
 *
 * Write two methods. One of them will return the sum of all numbers.
 * The other one will return the product (as an integer) of the numbers.
 */
public class Ex07_07 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int[] numbers = new int[10];
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = scanner.nextInt();
        }

        int sum = sum(numbers);
        int product = product(numbers);
        System.out.println("Sum: " + sum);
        System.out.println("Product: " + product);
    }

    private static int sum(int[] numbers) {
        int sum = 0;
        for (int number : numbers) {
            sum += number;
        }
        return sum;
    }

    private static int product(int[] numbers) {
        int product = 1;
        for (int number : numbers) {
            product *= number;
        }
        return product;
    }
}
