package com.github.pbochenski.codewars.kyu6;

/**
 * 8 kyu
 *
 * Find the first non-repeating character in a string.
 *
 * Return '#' if there is no non-repeating characters.
 *
 * "a" -&gt; "a"
 * "abacabad" -&gt; "c"
 * "" -&gt; "#"
 *
 * You can expect that all strings are valid.
 *
 * Bonus points if you can solve it with O(n) time without using
 * additional data structures.
 */
public class FirstNonRepeatingCharacter {

    public static char firstNonRepeatingLetter(String s) {
        for (char c : s.toCharArray()) {
            if (s.indexOf(c) == s.lastIndexOf(c)) {
                return c;
            }
        }
        return '#';
    }
}
