package nl.tudelft.informatica.jugbot.exceptions;

import nl.tudelft.informatica.jugbot.evaluation.Evaluator;

/**
 * Exception thrown when an evaluation fails.
 */
public class EvaluationException extends RuntimeException {

	private final Evaluator evaluator;
	private final String expression;

	/**
	 * Constructor.
	 * @param evaluator
	 * 	evaluator that threw the error
	 * @param expression
	 * 	expression that was evaluated
	 * @param cause
	 * 	the cause of the error
	 */
	public EvaluationException(Evaluator evaluator, String expression, Throwable cause) {
		super(String.format("Error while evaluating '%s'.", expression), cause);

		this.evaluator = evaluator;
		this.expression = expression;
	}

	/**
	 * Returns the evaluator that didn't finish with success.
	 * @return
	 * 	evaluator that threw the error
	 */
	public Evaluator getEvaluator() {
		return evaluator;
	}

	/**
	 * Returns the expression that didn't finish with success.
	 * @return
	 * 	expression that was evaluated
	 */
	public String getExpression() {
		return expression;
	}
}
