public class CopyFileFromResourceToWorkingDir {

    public static void main(String[] args) {
        Logger.getLogger(CopyFileFromResourceToWorkingDir.class.getName()).log(Level.INFO, "Starting File copy task.");
        Path workingDir = Paths.get(System.getProperty("user.dir"));
        Path path = Paths.get(workingDir + "/CopyFileFromResourceToWorkingDir.java");
        try {
            InputStream is = CopyFileFromResourceToWorkingDir.class.getResourceAsStream("/CopyFileFromResourceToWorkingDir.java");
            OutputStream os = Files.newOutputStream(path);
            byte[] buffer = new byte[4096];
            int bytesRead = -1;
            while ((bytesRead = is.read(buffer))!= -1) {
                os.write(buffer, 0, bytesRead);
            }
        } catch (IOException ex) {
            Logger.getLogger(CopyFileFromResourceToWorkingDir.class.getName()).log(Level.SEVERE, null, ex);
        }
        Logger.getLogger(CopyFileFromResourceToWorkingDir.class.getName()).log(Level.INFO, "Completed File copy task.");
    }
}
