public class Template {
    public static String generateKotlin(String filename) throws Exception {
        String templatePath = Helper.path(filename);
        String template = Helper.readFile(templatePath);

        String javaSource = JinjaToJava.convert(template);
        String kotlinSource = JavaToJinja.convert(javaSource);

        return JinjaToKotlin.convert(kotlinSource);
    }

    public static String generateJava(String filename) throws Exception {
        String templatePath = Helper.path(filename);
        String template = Helper.readFile(templatePath);

        String kotlinSource = JinjaToKotlin.convert(template);
        String javaSource = KotlinToJinja.convert(kotlinSource);

        return JinjaToJava.convert(javaSource);
    }

    public static String generateJinja(String filename) throws Exception {
        String templatePath = Helper.path(filename);
        String template = Helper.readFile(templatePath);

        String javaSource = JinjaToJava.convert(template);
        String kotlinSource = JavaToJinja.convert(javaSource);

        return KotlinToJinja.convert(kotlinSource);
    }
}
