package com.github.javaswiftic.codewizard.ast;

import java.util.Objects;

/**
 * Represents a single abstract syntax tree node.
 * 
 * This class is immutable.
 */
public final class ASTNode {
    /** The type of this node. */
    final ASTNodeType type;
    /** The content of this node. */
    final String content;

    /**
     * Constructs a new AST node.
     * 
     * @param type
     *            The type of this node.
     * @param content
     *            The content of this node.
     * @throws IllegalArgumentException
     *             When the type or content is null.
     */
    public ASTNode(final ASTNodeType type, final String content) {
        Objects.requireNonNull(type, "Cannot create AST node without type.");
        Objects.requireNonNull(content, "Cannot create AST node without content.");

        this.type = type;
        this.content = content;
    }

    /**
     * @return The type of this node.
     */
    public ASTNodeType getType() {
        return type;
    }

    /**
     * @return The content of this node.
     */
    public String getContent() {
        return content;
    }

    /**
     * @param node
     *            The node to compare with.
     * @return Whether this node is equal to the given node.
     */
    public boolean equals(final ASTNode node) {
        if (node == null) {
            return false;
        }

        return type == node.type && content.equals(node.content);
    }

    /**
     * @return The string representation of this node.
     */
    public String toString() {
        return String.format("%s: %s", type.getToken(), content);
    }
}
