    private final Set<FoglaltEsemeny> foglaltEsemenyek;

    private Lekozep(List<Szezon> szezons, Set<FoglaltEsemeny> foglaltEsemenyek) {
        super(szezons);
        this.foglaltEsemenyek = new HashSet<>(foglaltEsemenyek);
    }

    public Set<FoglaltEsemeny> getFoglaltEsemenyek() {
        return this.foglaltEsemenyek;
    }

    @Override
    public String toString() {
        return super.toString() + " [foglaltEsemenyek=" + foglaltEsemenyek + "]";
    }

    public static class Builder {
        private List<Szezon> szezons = new ArrayList<>();
        private Set<FoglaltEsemeny> foglaltEsemenyek = new HashSet<>();

        public Builder szezon(Szezon szezon) {
            this.szezons.add(szezon);
            szezon.setLekozep(this);
            return this;
        }

        public Builder foglaltEsemeny(FoglaltEsemeny foglaltEsemeny) {
            this.foglaltEsemenyek.add(foglaltEsemeny);
            return this;
        }

        public Lekozep build() {
            this.szezons.forEach(szezon ->
                    szezon.getEsemenyek().forEach(esemeny -> esemeny.setLekozep(this)));
            this.foglaltEsemenyek.forEach(esemeny -> esemeny.setLekozep(this));
            if (this.szezons.isEmpty()) {
                throw new IllegalStateException("Nem adott meg szezonet!");
            }
            return new Lekozep(this.szezons, this.foglaltEsemenyek);
        }
    }
