public class Student {
    private String name;
    private String facultyNumber;
    private Subject subject;
    private Integer points;

    public Student(String name, String facultyNumber, Subject subject, Integer points) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("Invalid name");
        }
        if (facultyNumber == null) {
            throw new IllegalArgumentException("Invalid faculty number");
        }
        if (subject == null) {
            throw new IllegalArgumentException("Invalid subject");
        }
        if (points < 0) {
            throw new IllegalArgumentException("Invalid points");
        }
        this.name = name;
        this.facultyNumber = facultyNumber;
        this.subject = subject;
        this.points = points;
    }

    @Override
    public int hashCode() {
        return this.facultyNumber.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == null ||!this.getClass().equals(obj.getClass())) {
            return false;
        }

        Student student = (Student) obj;
        return this.facultyNumber.equals(student.facultyNumber);
    }

    @Override
    public String toString() {
        return String.format("%s -> %s (%s, %s)", this.name, this.facultyNumber, this.subject, this.points);
    }
}
