public static String stripTags(String input) {
  int i=0;
  int length;
  char c;
  char[] string = input.toCharArray();
  length = string.length;
  while(i < length) {
      c = string[i];
      if(c == '<') {
          int j = i + 1;
          while(j < length && string[j]!= '>') {
              j++;
          }
          if(j >= length) {
              i = length;
              break;
          }
          for(int k = i; k < j; k++) {
              string[k] = (char) 0;
          }
          length = string.length;
          i = j + 1;
      }
      i++;
  }
  StringBuilder sb = new StringBuilder(string.length);
  for(int j = 0; j < length; j++) {
      c = string[j];
      if(c!= (char) 0) {
          sb.append(c);
      }
  }
  return sb.toString();
}
