public class PrintableStackTrace {

    public static String printException(Throwable ex, PrintWriter writer) {
        if (!Debug.isDebug()) {

            ex.printStackTrace(writer);
            writer.flush();
        } else {
            StackTraceElement[] stacktrace = ex.getStackTrace();
            int maxlen = stacktrace.length;

            writer.println( ex.getMessage() );
            for (int i = 0; i < maxlen; i++) {
                writer.println(i + " " + stacktrace[i].toString());
            }
            StringWriter stringWriter = new StringWriter();
            ex.printStackTrace(new PrintWriter(stringWriter));
            writer.print("Stacktrace: " + stringWriter.toString());
            writer.flush();
        }
        return writer.toString();
    }
}
