     * 该函数在抑制回溯细节之前检查环境是否为生产环境。
     */
    public static String debugger(Exception e) {
        if (isDebuggingEnabled()) {
            StringWriter sw = new StringWriter();
            e.printStackTrace(new PrintWriter(sw));
            return sw.toString();
        }
        return "";
    }

    /**
     * 检查是否已启用调试。
     */
    public static boolean isDebuggingEnabled() {
        // 这里假设在开发机上启用了调试，但在生产环境上禁用了调试。
        return true;
    }
}
