public class Trace {
    /**
     * Returns debug information.
     * 
     * This function checks the current environment before returning any backtrace
     * details.
     */
    public static String trace(boolean enabled) {
        if (enabled) {
            final StringWriter sw = new StringWriter();
            final PrintWriter w = new PrintWriter(sw, true);
            final StackTraceElement[] trace = Thread.currentThread().getStackTrace();
            for (int i = 2; i < trace.length; i++) { // Skip 2 stackitems, i.e. the
                final StackTraceElement element = trace[i];
                w.printf("%s::%s: %s\n", element.getClassName(), element.getMethodName(), element.getFileName());
            }
            return sw.toString();
        }
        return null;
    }
}
