    public static void main(String[] args) {
        System.out.println(calculateBonus(100));
        System.out.println(calculateBonus(2000));
        System.out.println(calculateBonus(20000));
        System.out.println(calculateBonus(1000));
    }

    public static int calculateBonus(int money) {
        if (money < 1000) {
            return 0;
        } else if (money < 10000) {
            return (int) money * 0.1;
        } else {
            return (int) money * 0.15;
        }
    }
}
