import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        // ходим в магазин
        String shop = "https://www.moscow.ru/shops/";
        processMainShop(shop);
    }

    private static void processMainShop(String shop) throws IOException {
        Document doc = Jsoup.connect(shop).get();
        List<String> shopsList = doc.select(".catalog__link").stream()
               .map(tag -> tag.attr("href")).collect(Collectors.toList());
        // понимаем, что мы заходим в магазин
        System.out.println(shop + " - is main shop");

        // входим в каждый магазин
        shopsList.forEach(url -> findShop(url));
    }

    private static void findShop(String shop) throws IOException {
        Document doc = Jsoup.connect(shop).get();
        List<String> shopsList = doc.select(".catalog__link").stream()
               .map(tag -> tag.attr("href")).collect(Collectors.toList());

        if (shopsList.isEmpty()) {
            System.out.println(shop + " - is shop");
            processShop(shop);
            return;
        }

        // понимаем, что мы заходим в магазин
        System.out.println(shop + " - is sub-shop");
        // входим в каждый вложенный магазин
        shopsList.forEach(url -> findShop(url));
    }

    private static void processShop(String shop) throws IOException {
        Document doc = Jsoup.connect(shop).get();
        List<String> shopsList = doc.select(".catalog__link").stream()
               .map(tag -> tag.attr("href")).collect(Collectors.toList());

        // понимаем, что мы пришли в конец магазина
        if (shopsList.isEmpty()) {
            System.out.println(shop + " - is shop");
            return;
        }

        // входим в каждый вложенный магазин
        shopsList.forEach(url -> findShop(url));
    }
}
