        int idx = random.nextInt(questions.size());
        // Try to set question id to a generated unique id if the id doesn't exist.
        Question question = questions.get(idx);
        while (question.getId()!= Integer.MIN_VALUE) {
            idx = random.nextInt(questions.size());
            question = questions.get(idx);
        }
        question.setId(currentId++);
        return question;
    }

