package com.github.bryanss84.minha.domain.user

import com.github.bryanss84.minha.domain.security.Crypto
import com.github.bryanss84.minha.domain.user.dto.AuthRequestDto
import com.github.bryanss84.minha.domain.user.dto.AuthResponseDto
import com.github.bryanss84.minha.domain.user.entity.AuthSession
import com.github.bryanss84.minha.domain.user.repository.AuthRepository
import org.springframework.stereotype.Service

@Service
class Auth {

    fun login(authRequestDto: AuthRequestDto): String {
        val authSession = AuthRepository.createSession(authRequestDto)
        return authSession.token
    }

    fun logout(token: String?) {
        if (token == null) {
            return
        }

        AuthRepository.deleteSession(token)
    }

    fun refresh(refreshToken: String?): String? {
        return AuthRepository.refresh(refreshToken)
    }

    fun getAuthSession(token: String?): AuthSession? {
        return AuthRepository.getAuthSession(token)
    }

    fun generateSignature(authRequestDto: AuthRequestDto, token: String?): String {
        val encodedAccessToken = authRequestDto.accessToken?.let { Crypto.hmacSha256(it, token) }
        val encodedRefreshToken = authRequestDto.refreshToken?.let { Crypto.hmacSha256(it, token) }
        val encodedSignature = encodedAccessToken + encodedRefreshToken
        return Crypto.hmacSha256(encodedSignature, authRequestDto.signature)
    }

    fun getAuthResponseDto(authRequestDto: AuthRequestDto, authSession: AuthSession): AuthResponseDto? {
        val authResponseDto = AuthResponseDto()
        authResponseDto.accessToken = authSession.accessToken
        authResponseDto.refreshToken = authSession.refreshToken
        authResponseDto.signature = authSession.signature

        return authResponseDto
    }

