static public boolean verifyJWT(String jwt) {
    // Kiểm tra jwt có được mã hóa theo chuẩn UTF-8 không
    if (!jwt.matches("([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2})*={0,2}")) {
        return false;
    }
    // Bắt đầu giải mã JWT
    jwt = jwt.replace(" ", "+");
    int pad = jwt.length() % 4;
    if (pad > 0) {
        jwt += "=".repeat(4 - pad);
    }
    String decodedJwt = new String(Base64.getDecoder().decode(jwt));
    // Trích xuất chuỗi mã hóa và token của JWT
    int separator = decodedJwt.indexOf('.');
    if (separator < 1) {
        return false;
    }
    String encodedHeader = decodedJwt.substring(0, separator);
    String encodedPayload = decodedJwt.substring(separator + 1, decodedJwt.lastIndexOf('.'));
    // Token JWT không được mã hóa
    if (!encodedHeader.equals("") ||!encodedPayload.equals("")) {
        return false;
    }
    // Kiểm tra sự chuẩn bị và tính toán dữ liệu thông báo
    Map<String, String> header = new HashMap<String, String>();
    String[] parts = encodedPayload.split(",");
    for (String part : parts) {
        String[] keyValue = part.split("=");
        header.put(keyValue[0], keyValue[1].replace("\"", ""));
    }
    // Kiểm tra thuật toán chữ ký 
    if (header.get("alg").equals("none")) {
        return true;
    } else {
        return false;
    }
}
