        if (parts.length!= 3) {
            throw new TokenVerificationException("Invalid token format");
        }

        String algorithm = parts[0].replace("Bearer ", "");

        String tokenHeader = Base64Utils.decodeToString(parts[0]);
        String tokenPayload = Base64Utils.decodeToString(parts[1]);

        String signature = parts[2];

        JsonWebToken jwt = parse(tokenPayload);
        if (jwt.getSignature() == null) {
            throw new TokenVerificationException("No signature in token");
        }

        String canonicalHeaderWithoutSignature = canonicalizeHeader(tokenHeader) + "." + canonicalizePayload(tokenPayload);
        String expectedSignature = calculateSignature(secret, canonicalHeaderWithoutSignature);
        if (!Base64Utils.encodeToString(expectedSignature).equals(signature)) {
            throw new TokenVerificationException("Invalid signature");
        }

        if (!algorithms.containsKey(JwtAlgorithms.fromName(algorithm))) {
            throw new TokenVerificationException("Algorithm not supported");
        }

        if (!JwtAlgorithms.HS256.equals(algorithm) &&!JwtAlgorithms.NONE.equals(algorithm)) {
            throw new TokenVerificationException("Algorithm not supported");
        }

        return true;
    }
}
