        }
        final String header = parts[0];
        final String body = parts[1];
        final String signature = parts[2];
        final byte[] headerBytes = Base64.getDecoder().decode(header);
        final byte[] bodyBytes = Base64.getDecoder().decode(body);
        final Map<String, String> headerMap = new HashMap<>();
        for (String param : headerBytes.toString().split("&")) {
            String[] pair = param.split("=");
            headerMap.put(pair[0], pair[1]);
        }
        String algorithm;
        if (headerMap.containsKey("alg")) {
            algorithm = headerMap.get("alg");
        } else {
            algorithm = null;
        }
        final boolean signatureValidate = validateSignature(body, signature, algorithm);
        if (!signatureValidate) {
            return false;
        } else {
            return true;
        }
    } catch (Exception ignored) {
        return false;
    }
}

