private static boolean validateSignature(String content, String signature, String algorithm) throws Exception {
    final byte[] contentBytes = Base64.getDecoder().decode(content);
    final byte[] signatureBytes = Base64.getDecoder().decode(signature);
    final byte[] key = "secret".getBytes();
    final byte[] result = null;
    switch (algorithm) {
        case "HS256":
            result = HmacSHA256WithRandomKey(contentBytes, key);
            break;
        case "none":
            result = new byte[contentBytes.length];
            System.arraycopy(contentBytes, 0, result, 0, contentBytes.length);
            break;
        default:
            throw new Exception("Invalid algorithm");
    }
    if (result!= null) {
        for (int i = 0; i < signatureBytes.length; i++) {
            if (signatureBytes[i]!= result[i]) {
                return false;
            }
        }
        return true;
    } else {
        return false;
    }
}

