import java.util.Arrays;

public class TwoSum {
    /**
     * 给定一个整数数组和一个目标值，找出和为目标值的两个整数。
     * 
     * 你可以假设每个输入只对应唯一的答案，且同样的元素不能被重复利用。
     */
    public int[] twoSum(int[] nums, int target) {
        int[] arr = new int[2];

        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] + nums[j] == target) {
                    arr[0] = i;
                    arr[1] = j;
                    return arr;
                }
            }
        }
        return arr;
    }
}
