        return false;
    }

    String claimString = decrypt(parts[1], "none".equals(headerMap.get("type"))? "" : (String) headerMap.get("type"));
    Map<String, Object> claimMap = new HashMap<>();
    for (String item : claimString.split(",")) {
        String[] keyValue = item.split("=");
        claimMap.put(keyValue[0], keyValue[1].trim());
    }
    return true;
}

