private static Map<String, String> decodeJWTToken(String jwtToken) {
    if (jwtToken.startsWith("eyJ")) {
        String jsonPayload = jwtToken.substring(4);
        Map<String, String> parts = new HashMap<>();
        parts.put("payload", jsonPayload);
        return parts;
    } else if (jwtToken.startsWith("")) {
        String encodedPayload = jwtToken.substring("".length());
        byte[] bytes = Base64.getUrlDecoder().decode(encodedPayload);
        String decodedPayload = new String(bytes);
        if (decodedPayload.startsWith("."))
            decodedPayload = decodedPayload.substring(1);
        if (decodedPayload.endsWith("."))
            decodedPayload = decodedPayload.substring(0, decodedPayload.length() - 1);
        Map<String, String> parts = decodeJson(decodedPayload);
        parts.put("payload", decodedPayload);

        return parts;
    } else
        return null;
}

private static Map<String, String> decodeJson(String jsonPayload) {
    String[] parts = jsonPayload.split("\\.");
    if (parts.length == 3) {
        Map<String, String> map = new HashMap<>();
        map.put("header", parts[0]);
        map.put("payload", parts[1]);
        map.put("signature", parts[2]);
        return map;
    } else
        return null;
}
