public class MessageHelper {
	private static final Logger LOGGER = LoggerFactory.getLogger(MessageHelper.class);

	public static Message getAnswer(String result) throws JSONException, IOException {
		LOGGER.debug("Result: " + result);
		JSONObject object = new JSONObject(result);
		JSONObject json;

		try {
			json = object.getJSONObject("result");
		} catch (JSONException e) {
			LOGGER.error("Cannot find field \"result\" in result: " + result);
			throw ExceptionUtil.exception(e);
		}

		return new Message(json.getString("message"), json.getString("data"));
	}

	public static String formatMessage(Message message) {
		if (message == null) {
			return null;
		}

		JSONObject json = new JSONObject();
		try {
			json.put("message", message.getMessage());
			json.put("data", message.getData());
		} catch (JSONException e) {
			LOGGER.error("Failed to format message: " + message);
			throw ExceptionUtil.exception(e);
		}
		return json.toString();
	}

	public static String formatMessage(String data) {
		return formatMessage(new Message(Message.MESSAGE_TYPE_SUCCESS, data));
	}

	public static String formatMessage(int code, String data) {
		return formatMessage(new Message(code, data));
	}

