public class ReadTextFile {

    public ReadTextFile() {
    }

    public Map<String, Integer> readFile(Map<String, Integer> map, String file) {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(file), Charset.forName("UTF-8"))) {

            String line = null;
            while ((line = reader.readLine())!= null) {
                String[] words = line.split("[^a-zA-ZäöüÄÖÜáéíóúÁÉÍÓÚß]");
                for (String word : words) {
                    word = word.toLowerCase();
                    if (map.containsKey(word)) {
                        map.put(word, map.get(word) + 1);
                    } else {
                        map.put(word, 1);
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return map;
    }
