/**
 * Codewriting
 *
 * <p>
 * You are given an array of strings. Write a function that returns another array
 * containing the longest string in the array. If there are two or more possible
 * answers, return any one.
 * <p>
 * Example:
 * <p>
 * For inputArray = ["aba", "aa", "ad", "vcd", "aba"], the output should be
 * allLongestStrings(inputArray) = ["aba", "vcd", "aba"].
 */
@QuestionType(questionType = QuestionType.QUESTION_TYPE.CHALLENGE)
public class AllLongestStrings {
  public static List<String> allLongestStrings(List<String> inputArray) {
    // your code here
    Set<String> answer = new LinkedHashSet<>();

    String longest = "";
    for (String word : inputArray) {
      if (word.length() > longest.length()) {
        longest = word;
        answer.clear();
        answer.add(word);
      } else if (word.length() == longest.length()) {
        answer.add(word);
      }
    }

    return new ArrayList<>(answer);
  }
}
