void findWord(const std::string &filename, std::ifstream &inputFile, std::ofstream &outputFile) {
  int counter = 0;
  char c;
  inputFile >> c;
  while (inputFile.good()) {
    if (c!='') {
      counter++;
    }
    inputFile.get(c);
  }
  outputFile << counter;
}

