    public static String writeDocumentToString(org.w3c.dom.Document doc) {
        StringWriter sw = new StringWriter();
        try {
            doc.normalize();
            org.apache.xml.serialize.OutputFormat format = new org.apache.xml.serialize.OutputFormat(doc);
            format.setLineWidth(65);
            format.setIndenting(true);
            org.apache.xml.serialize.XMLSerializer serializer = new org.apache.xml.serialize.XMLSerializer(sw, format);
