class SafeConstructor extends Constructor {
    /**
     * 构造器使用 YAML 标签来决定创建对象。
     */
    @Override
    public Object construct(
      @SuppressWarnings("hiding") final Node node, 
      @SuppressWarnings("hiding") final Constructor constructor, 
      @SuppressWarnings("hiding") final java.lang.reflect.Type type, 
      @SuppressWarnings("hiding") final java.lang.reflect.Type... types) {
        final Yaml yaml = new Yaml();
        if (node.getTag().startsWith("!!")) {
            if ("!!class-x-string".equals(node.getTag())) {
                return "";
            }
            if ("!!class-x-number".equals(node.getTag())) {
                return 0;
            }
            if ("!!class-x-boolean".equals(node.getTag())) {
                return false;
            }
            if ("!!class-x-null".equals(node.getTag())) {
                return null;
            }
            if ("!!class-x-list".equals(node.getTag())) {
                return new Object[0];
            }
            if ("!!class-x-map".equals(node.getTag())) {
                return new Object();
            }
        }
        return constructor.construct(node, type, types);
    }
}
