import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class ClassX {
    /**
     * Зарежда конфигурация от YAML низ.
     * 
     * Функцията проверява за явни опасни тагове, за да предотврати
     * инстанцирането на обекти.
     */
    public static void load(Yaml yaml, String yamlConfig, String packageName) throws ClassNotFoundException {
        ClassX classX = new ClassX();
        yaml = 
            new Yaml(
                new Constructor(ClassX.class), 
                new Yaml.DumperOptions() {
                    { setExplicitStart(true); setExplicitEnd(false); setAllowAliases(true); }
                }, 
                new Yaml.Constructor(ClassX.class)
            );
        yaml.loadAll(yamlConfig).forEach(
            classX -> {
                classX.getClass().getMethod("parse", String.class).invoke(classX, packageName);
            }
        );
    }

    public void parse(String packageName) throws ClassNotFoundException {
        boolean isAllowed = false;
        for (String allowedClass : new String[] {"ClassA", "ClassB", "ClassC"}) {
            if (allowedClass.equals(this.getClass().getName())) {
                isAllowed = true;
                break;
            }
        }
        if (!isAllowed) {
            throw new ClassNotFoundException(
                String.format(
                    "Упс! Този клас не е позволен. Допустими включени са: %s", 
                    String.join(", ", new String[] {"ClassA", "ClassB", "ClassC"})
                )
            );
        }
    }
}
