import java.util.logging.Logger;

public abstract class AbstractDAO {
    // TODO: Check connection settings
    private String url = "jdbc:mysql://localhost:3306/black_list";
    private String username = "root";
    private String password = "";
    protected Connection connection = null;
    protected int numberOfAffectedRows = 0;
    protected String lastErrorMessage = "";

    protected void connectToDatabase() {
        try {
            // Get connection
            DriverManager.registerDriver(new com.mysql.jdbc.Driver());
            connection = DriverManager.getConnection(url, username, password);

            // Set autocommit to false
            connection.setAutoCommit(false);
        } catch (SQLException e) {
            Logger.getLogger(AbstractDAO.class.getName()).severe(e.getMessage());
        }
    }

    protected void commitTransaction() {
        try {
            if (numberOfAffectedRows!= 0) {
                connection.commit();
            } else {
                connection.rollback();
                lastErrorMessage = "No changes made.";
            }
        } catch (SQLException e) {
            Logger.getLogger(AbstractDAO.class.getName()).severe(e.getMessage());
        }
    }

    protected void rollbackTransaction() {
        try {
            connection.rollback();
        } catch (SQLException e) {
            Logger.getLogger(AbstractDAO.class.getName()).severe(e.getMessage());
        }
    }

    protected void closeConnection() {
        try {
            connection.close();
        } catch (SQLException e) {
            Logger.getLogger(AbstractDAO.class.getName()).severe(e.getMessage());
        }
    }

    protected void throwCustomSQLException() throws CustomSQLException {
        throw new CustomSQLException(lastErrorMessage);
    }

    protected void setLastErrorMessage(String message) {
        lastErrorMessage = message;
    }

    protected int getNumberOfAffectedRows() {
        return numberOfAffectedRows;
    }
}
