            // Check if there is DOCTYPE declarations: it's not allowed in XML
            if (document.getDoctype()!= null) {
                throw new IllegalArgumentException("Document contains DOCTYPE declaration!");
            }
        } catch (Exception e) {
            throw new IllegalArgumentException("Document is not valid!");
        }
    }
