import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Abstraction over Java AST Types.
 */
public interface Type {
    /**
     * Returns the qualified name of the type as a string
     * @return String
     */
    String qualifiedName();

    /**
     * Returns the simple name of the type as a string
     * @return String
     */
    String simpleName();

    /**
     * Returns the fully qualified package name of the type as a string
     * @return String
     */
    default String packageName() {
        return fullQualifiedName().substring(0, fullQualifiedName().lastIndexOf('.'));
    }

    /**
     * Returns the full qualified name of the type as a string
     * @return String
     */
    String fullQualifiedName();

    /**
     * Returns whether this type is Void
     * @return boolean
     */
    default boolean isVoid() {
        if (this instanceof VoidType) {
            return true;
        }
        if (this instanceof ClassOrInterfaceType) {
            return this.asClassOrInterfaceType().get().isVoidType();
        }
        return false;
    }

    /**
     * Returns whether this type is Void
     * @return boolean
     */
    default boolean isNull() {
        if (this instanceof NullType) {
            return true;
        }
        if (this instanceof ClassOrInterfaceType) {
            return this.asClassOrInterfaceType().get().isNullType();
        }
        return false;
    }

    /**
     * Returns whether this type is Number
     * @return boolean
     */
    default boolean isNumber() {
        return Stream.of(
                this,
                this.asPrimitiveType(),
                this.asClassOrInterfaceType(),
                this.asArrayType()
        ).flatMap(Optional::stream).anyMatch(t -> t instanceof NumberType);
    }

    /**
     * Returns whether this type is a primitive type
     * @return boolean
     */

}
