	public Player(int id) {
		this.id = id;
		this.position = new Coordinates(0, 0);
	}

	public int getId() {
		return id;
	}

	public Coordinates getPosition() {
		return position;
	}

	public void setPosition(Coordinates position) {
		this.position = position;
	}

	public List<Coordinates> getPositions() {
		return positions;
	}

	public void setPositions(List<Coordinates> positions) {
		this.positions = positions;
	}

	@Override
	public String toString() {
		return "Player [" + "id=" + id + ", position=" + position.toString() + "]";
	}

	public Coordinates getMinPosition() {
		return positions.stream().min(Coordinates::compareTo).get();
	}

	public Coordinates getMaxPosition() {
		return positions.stream().max(Coordinates::compareTo).get();
	}

}
