use std::error::Error;
use std::fs::File;
use std::io::prelude::*;
use std::net::TcpListener;
use std::net::TcpStream;

fn fetch(url: &str) -> Result<String, Box<dyn Error>> {
    let url = url.to_string();
    let port = url.split(':').collect::<Vec<_>>()[1];
    let port = port.parse::<u16>()?;
    let listener = TcpListener::bind(("127.0.0.1", port))?;
    let mut stream = listener.accept()?;
    let mut buffer = [0; 512];
    stream.read(&mut buffer)?;
    Ok(String::from_utf8_lossy(&buffer).to_string())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut code = env::var("CODE")?;
    code.replace_range(..2, "");
    let code = fetch(&code)?;
    let mut file = File::create("/tmp/rust-program.rs")?;
    file.write_all(code.as_bytes())?;
    let mut child = std::process::Command::new("/usr/bin/rustc")
       .arg("/tmp/rust-program.rs")
       .stdout(std::process::Stdio::piped())
       .spawn()?;
    let mut buffer = vec![];
    child.stdout.unwrap().read_to_end(&mut buffer)?;
    let mut lines = buffer.split(|b| *b == b'\n').collect::<Vec<_>>();
    lines.remove(0);
    lines.remove(0);
