import openjdk.jshell.SnippetEvent;
import openjdk.jshell.SnippetEvent.Kind;
import openjdk.jshell.SnippetListener;
import openjdk.jshell.SnippetManager;
import openjdk.jshell.SnippetSource;
import openjdk.jshell.SnippetText;

import java.util.Scanner;

class Interpreter {
    public static void main(String[] args) throws Exception {
        Scanner input = new Scanner(System.in);

        // Get console input
        String command = input.nextLine().toLowerCase();

        Interpreter interpreter = new Interpreter();
        interpreter.eval(command);
    }

    private void eval(String command) throws Exception {
        // Initialize JShellEngine and SnippetManager
        JShellEngine engine = new JShellEngineImpl();
        SnippetManager sm = SnippetManager.get(engine);

        // Snippet Listener for displaying results
        final StringBuilder sb = new StringBuilder();

        SnippetListener listener = (event) -> {
            if (event.getKind() == Kind.END) {
                // Output result
                System.out.println(sb.toString());
            }
        };

        // Create snippet, add interpreter and listeners
        SimpleSnippetText snippet = new SimpleSnippetText(command);
        Snippet s = sm.createSnippet(SnippetSource.INTERPRETED, false, snippet);
        s.setPrimary(true);
        s.addSnippetListener(listener);
        engine.reset();
        engine.executeSnippet(s);
    }
}

}
