package il.co.topjava.jumble;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;

import java.util.Optional;
import java.util.Random;
import java.util.stream.Stream;

import static java.util.stream.Collectors.joining;

@Controller
public class JumbleController {
    private final Random random = new Random();
    private final JumbleDictionary dictionary = new JumbleDictionary(random);

    @RequestMapping("/jumble.txt")
    @ResponseBody
    public String getJumbled() {
        return Stream
           .generate(() -> dictionary.getRandomWord())
           .limit(10)
           .map(JumbleDictionary::jumble)
           .map(String::toUpperCase)
           .collect(joining("\n"));
    }

    @RequestMapping("/jumble-word")
    @ResponseBody
    public String getJumbled(String word) {
        return Optional
           .ofNullable(word)
           .map(JumbleDictionary::jumble)
           .map(String::toUpperCase)
           .orElse("INVALID");
    }

}
