# Time Complexity: O(n)
# Space Complexity: O(n)

def quartile(array, median):
    assert len(array) > 0
    assert all(isinstance(element, int) for element in array)

    array.sort()
    if median > len(array) / 2:
        median -= len(array) / 2
    else:
        median += 1
        median //= 2

    if len(array) % 2 == 0:
        return (array[median - 1] + array[median]) / 2
    else:
        return array[int(median + 0.5)]


