package io.github.n0l1.classX.logic;

import java.util.ArrayList;
import java.util.List;

import java.util.regex.Pattern;

import io.github.n0l1.classX.model.QuestionPart;

public class Parser {

    private final Pattern linePattern = Pattern.compile("/\\*\\|\\|([^|]*)\\|\\|(.*)\\|\\|/");
    private List<QuestionPart> parts = new ArrayList<>();

    public List<QuestionPart> parse(String text) {
        text = text.replaceAll("\\*\\*\\*", "");
        parts.clear();

        java.util.regex.Matcher matcher = linePattern.matcher(text);
        while(matcher.find()) {
            parts.add(new QuestionPart(matcher.group(1), matcher.group(2)));
        }

        return parts;
    }
}
