public class ServerImpl implements Server {
    private final int port;
    private final ServerSocket serverSocket;

    public ServerImpl(int port) throws IOException {
        this.port = port;
        serverSocket = new ServerSocket(port);
    }

    @Override
    public void start() throws IOException {
        while (true) {
            try {
                Socket socket = serverSocket.accept();
                new ServerThread(socket).start();
            } catch (IOException ignored) {
            }
        }
    }

    /**
     * Поток обслуживания клиента.
     */
    private static class ServerThread extends Thread {
        private final Socket socket;

        public ServerThread(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
                 BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"))) {
                String code = bufferedReader.readLine();
                int index = Integer.parseInt(bufferedReader.readLine());
                String[] answers = bufferedReader.readLine().split(" ");
                String result = Server.submit(code, answers[index]);
                bufferedWriter.write(result);
                bufferedWriter.newLine();
                bufferedWriter.flush();
            } catch (IOException ignored) {
            } finally {
                try {
                    socket.close();
                } catch (IOException ignored) {
                }
            }
        }
    }
}
