        this.message = message;
    }

    public int getCode() {
        return code;
    }

    public String getMessage() {
        return message;
    }

    public static Exercise fromFile(File file) {
        try (FileInputStream input = new FileInputStream(file)) {
            byte[] buffer = new byte[(int) file.length()];
            input.read(buffer);
            String contents = new String(buffer, StandardCharsets.UTF_8);

            return new Exercise(extractCode(contents), extractMessage(contents));
        } catch (Exception e) {
            System.err.println("Error reading '" + file.getAbsolutePath() + "'!");
            return new Exercise(0, "Error reading '" + file.getAbsolutePath() + "'.");
        }
    }

    public void print(PrintStream printer) {
        printer.println(code);
        printer.println(message);
    }

    private static int extractCode(String message) {
        String[] parts = message.split("\n");
        return Integer.parseInt(parts[0]);
    }

    private static String extractMessage(String message) {
        String[] parts = message.split("\n");
        return parts[parts.length - 1].trim();
    }

    public static void main(String... args) {
        for(File file : args[0].listFiles()) {
            if(file.isFile()) {
                Exercise exercise = Exercise.fromFile(file);
                System.out.println(file.getName());
                exercise.print(System.out);
            } else if(!file.isHidden()) {
                System.out.println("== " + file.getName());
                System.out.println();
            }
        }
    }
